    {"대지": "1대지: 믿음으로 구하라 (자세)", "내용": "믿음으로 구한다는 것은 하나님의 성품(후히 주시고 꾸짖지 않으시는)을 신뢰하며 구하는 것이다. 기도의 효력은 기도자의 열정이 아니라 하나님의 신실함에 근거한다", "예화_적용": "의사를 신뢰하는 환자가 처방을 따르듯 하나님을 신뢰하는 성도가 기도로 나아간다"},
    {"대지": "2대지: 의심하지 말라 (경고)", "내용": "의심(디아크리노)은 마음이 둘로 갈라진 것이다. 하나님을 믿으면서 동시에 불신하는 모순된 상태이다", "예화_적용": "한 발은 배에 한 발은 부두에 둔 사람은 반드시 빠진다. 믿음과 의심 사이에 서 있으면 넘어진다"},
    {"대지": "3대지: 바다 물결의 경고 (결과)", "내용": "의심하는 자는 바람에 밀려 요동하는 물결과 같다. 환경에 좌우되고 방향이 없으며 안정이 없는 상태이다", "예화_적용": "풍향계는 바람의 방향만 보여줄 뿐 자기 방향이 없다. 의심하는 자의 마음도 환경이 정하는 대로 흔들린다"},
    {"대지": "결론", "내용": "믿음은 환경 너머에 계신 하나님을 바라보는 것이다. 바람과 파도를 보지 말고 파도 위를 걸으신 주님을 바라보자", "예화_적용": "베드로가 주님을 보았을 때는 물 위를 걸었고 파도를 보았을 때는 빠졌다. 시선의 방향이 믿음의 방향이다"}
