    {"교리": "하나님의 주권과 인간의 책임", "설명": "하나님은 후히 주시겠다고 약속하셨으나(5절) 인간에게는 믿음으로 구할 책임이 있다(6절). 은혜와 책임은 대립이 아니라 협력이다", "관련구절": "빌 2:12-13, 고전 3:6-7, 약 2:17, 엡 2:8-10"}
