    {"원어": "παρελεύσεται (파렐류세타이)", "의미_문법": "지나가다 - 미래 중간태. 사라지다, 소멸하다", "설교포인트": "부는 '지나간다.' 미래형으로 표현되어 반드시 올 현실임을 강조한다. 지나가지 않는 것에 투자하는 것이 지혜이다"}
