    {"항목": "초대교회의 부유한 신자", "내용": "초대교회에 부유한 신자도 있었으며(행 4:36-37, 행 16:14) 이들은 공동체를 위해 재산을 나누었다. 그러나 일부는 부를 통해 교회 안에서 특권을 누리려 했다(약 2:1-4)", "목회적활용": "부유한 성도에게 겸손과 나눔의 의무를 가르치되 정죄가 아닌 사랑으로 인도하라"}
