    {"구분": "다윗의 범죄", "내용": "다윗은 밧세바를 보고 탐하는 욕심이 간음의 죄를 낳았고 간음이 살인으로 발전했으며 결국 아이의 죽음으로 이어졌다(삼하 11-12장). 욕심-죄-사망의 전형적 과정이다", "그리스도연결": "그리스도의 보혈은 이 죽음의 연쇄를 끊는다. 다윗의 회개 후 하나님의 용서가 임한 것은 은혜의 예표이다(시 51편)"}
