    {"구분": "이사야의 입술 정결", "내용": "이사야는 하나님을 만났을 때 '화로다 나여 나는 입술이 부정한 사람'(사 6:5)이라 고백했다. 불 숯으로 입술이 정결케 된 후에야 사명을 받았다(사 6:6-8). 혀의 정결이 사역의 전제 조건이다", "그리스도연결": "그리스도는 입에 아무 궤사도 없으셨다(벧전 2:22). 그분의 입술은 완전히 정결하셨으며 이것이 참된 경건의 모범이다"}
