    {"교리": "그리스도론과 윤리", "설명": "야고보는 '영광의 주 예수 그리스도'라는 고백에서 윤리적 명령을 이끌어낸다. 그리스도론(누구를 믿는가)이 윤리(어떻게 사는가)의 기초가 된다", "관련구절": "빌 2:5-8, 고후 8:9, 요 13:14-15, 골 3:11"}
