    {"구분": "룻과 보아스", "내용": "보아스는 이방 여인이자 과부인 룻을 차별하지 않고 동등하게 대우했다(룻 2장). 사회적 편견을 넘어선 사랑의 예표이다", "그리스도연결": "그리스도는 유대인과 이방인의 구별을 없애시고 한 새 사람을 만드셨다(엡 2:14-16)"}
