    {"상황": "무의식적으로 외모나 지위로 사람을 판단하는 성도", "성경원리": "편파는 의식적이든 무의식적이든 하나님의 공평하심에 어긋나는 것이다. 하나님은 마음을 보시며 모든 사람에게 동일한 존엄을 부여하셨다", "실제적용": "자신의 무의식적 편견을 인식하도록 도우라. 구체적인 상황에서 어떤 기준으로 사람을 판단하고 있는지 점검하도록 안내하라"}
