    {"원어": "πλησίον (플레시온)", "의미_문법": "이웃, 가까운 자 - 부사/명사. 가까이에 있는 사람", "설교포인트": "이웃은 특정인이 아니라 가까이에 있는 모든 사람이다. 선한 사마리아인 비유에서 예수님은 이웃의 범위를 모든 사람으로 확대하셨다(눅 10:29-37)"}
