    {"교리": "편파와 사랑의 양립 불가", "설명": "야고보는 8-9절에서 이웃 사랑과 편파를 대비시킨다. 사랑의 법을 지키면 잘하는 것이지만(8절) 외모로 차별하면 죄를 짓는 것이다(9절). 두 가지는 양립할 수 없다", "관련구절": "약 2:9, 요일 4:20-21, 요일 3:17-18, 마 5:43-48"}
