    {"구분": "레위기의 이웃 사랑", "내용": "레 19:18의 원래 문맥에서 '이웃'은 이스라엘 동족을 가리켰으나 레 19:34에서 '나그네'까지 확장되었다. 사랑의 범위는 점진적으로 넓어진다", "그리스도연결": "그리스도는 사랑의 대상을 '원수'까지 확대하셨다(마 5:44). 이것이 왕의 법의 완전한 실현이다"}
