    {"원어": "πταίσῃ (프타이세)", "의미_문법": "넘어지다, 실족하다 - 아오리스트 가정법 능동태 3인칭 단수", "설교포인트": "프타이오는 단순한 실수가 아니라 도덕적·영적 실족을 의미합니다. 인간의 본질적 연약함을 드러냅니다"},
    {"원어": "ἔνοχος (에노코스)", "의미_문법": "유죄의, 책임이 있는 - 형용사, 남성 단수 주격", "설교포인트": "법정 용어로 '유죄 판결을 받은 자'를 뜻합니다. 하나의 범죄가 전체 율법 앞에 유죄로 만드는 엄중한 현실입니다"}
