  "표2_역사적배경": [
    {"항목": "율법의 통일성에 대한 유대적 이해", "내용": "랍비 전승에서도 율법은 하나의 유기적 전체로 이해되었다. 탈무드에 '하나의 계명을 범하는 자는 모든 계명을 범한 것과 같다'는 가르침이 있다(바벨론 탈무드 쉐부오트 29a). 야고보는 이 유대적 전통을 따르면서 편파를 사소한 실수가 아닌 율법 전체를 범하는 중죄로 규정한다", "목회적활용": "성도들이 자신의 특정 죄를 사소하게 여기는 경향이 있을 때, 하나님의 율법이 유기적 전체임을 가르치라. '큰 죄'와 '작은 죄'의 구분은 인간적 기준이지 하나님의 기준이 아님을 분명히 하라"},
    {"항목": "편파와 율법 위반의 연결", "내용": "야고보는 2:8의 '왕의 법(사랑의 법)'에서 2:9의 편파 정죄로, 다시 2:10의 율법의 통일성으로 논리를 전개한다. 편파는 단순한 예의 문제가 아니라 하나님의 율법 전체를 깨뜨리는 행위임을 보여준다", "목회적활용": "교회 내에서 사람을 차별하는 행위가 '예배 질서'나 '교회 문화'라는 이름으로 정당화되지 않도록 주의하라"}
  ],
  "표3_신학적의미": [
    {"교리": "율법의 유기적 통일성", "설명": "율법은 613개의 개별 조항이 아니라 하나님의 뜻을 반영하는 하나의 전체다. 하나를 범하면 전체를 범한 것이 되는 이유는, 모든 계명의 근원이 되시는 하나님 한 분의 뜻을 거역하는 것이기 때문이다. 이는 인간의 자력 구원 불가능성을 드러내며 그리스도의 대속의 필요성을 역설한다", "관련구절": "마 5:19, 갈 3:10, 갈 5:3, 신 27:26"},
    {"교리": "전적 타락과 은혜의 필요", "설명": "온 율법을 지키다가도 하나만 범하면 유죄라는 선언은 인간의 도덕적 노력만으로는 하나님 앞에 의로울 수 없음을 보여준다. 이는 오직 그리스도의 의를 덧입어야만 하나님 앞에 설 수 있다는 복음의 핵심 진리를 뒷받침한다", "관련구절": "롬 3:20, 롬 3:23-24, 빌 3:9"}
  ],
  "표4_예표론": [
    {"구분": "율법의 완전한 성취자 그리스도", "내용": "온 율법을 하나도 범하지 않고 완전히 지킨 분은 오직 예수 그리스도뿐이다. 모든 사람이 하나라도 범하여 유죄가 되는 이 절대적 기준 앞에, 율법을 온전히 성취하신 그리스도만이 인류의 유일한 소망이 된다", "그리스도연결": "예수님은 율법의 모든 요구를 완벽히 성취하셨다(마 5:17). 우리가 율법 하나를 범하여 유죄가 될 때, 그리스도는 우리를 대신하여 율법의 저주를 받으셨다(갈 3:13). 그의 완전한 의가 우리에게 전가됨으로 우리는 율법의 정죄에서 벗어난다"}
  ],
  "표5_매튜헨리": [
    {"영어원문": "A man may be said to break all the commands when he offends willfully against any one. The same authority that enacted one command enacted all; and therefore, if we willfully break any one, we set at naught the authority of the Lawgiver.", "한국어번역": "어떤 사람이 고의로 하나의 계명을 어기면 모든 계명을 어긴 것이라 할 수 있다. 한 계명을 제정하신 동일한 권위가 모든 계명을 제정하셨기 때문이다. 그러므로 우리가 고의로 하나라도 어기면 입법자의 권위를 무시하는 것이다", "핵심통찰": "문제의 핵심은 개별 조항이 아니라 입법자이신 하나님의 권위다. 하나의 계명을 의도적으로 무시하는 것은 곧 하나님 자체를 무시하는 행위다"}
  ],
  "표6_설교자료": [
    {"대지": "제목", "내용": "하나를 범하면 전부를 범한 것 — 율법의 무서운 통일성", "예화_적용": "율법 앞에 선 인간의 현실과 은혜의 필요를 깨닫는 설교"},
    {"대지": "서론", "내용": "우리는 흔히 죄에 등급을 매기고 '나는 그 정도까지는 아니다'라고 자위합니다. 그러나 야고보는 율법의 절대적 기준을 선언합니다.", "예화_적용": "시험에서 100문제 중 99개를 맞추고 1개를 틀리면 만점이 아닙니다. 율법도 마찬가지로, 하나라도 범하면 '범법자'가 됩니다."},
    {"대지": "1대지: 율법은 하나의 사슬이다 (통일성)", "내용": "온 율법은 하나님의 뜻이라는 하나의 사슬로 연결되어 있다. 사슬은 가장 약한 고리에서 끊어진다. 하나의 계명을 범하면 전체 사슬이 끊어지는 것과 같다.", "예화_적용": "유리창 하나만 깨져도 전체 창의 방풍 기능이 사라지듯, 하나의 율법 위반이 전체 관계를 손상시킨다."},
    {"대지": "2대지: 문제는 행위가 아니라 권위다 (입법자)", "내용": "야고보가 말하는 핵심은 계명의 개수가 아니라 계명 뒤에 계신 하나님의 권위다. 하나를 범한다는 것은 그 계명을 주신 하나님의 권위를 부정하는 것이다.", "예화_적용": "직장에서 상사의 지시 열 가지 중 아홉 가지를 잘 수행하고 하나를 무시하면, 문제는 그 하나의 업무가 아니라 상사의 권위를 무시한 것이 된다."},
    {"대지": "3대지: 은혜만이 답이다 (복음)", "내용": "이 율법의 절대적 기준은 인간의 자력 구원이 불가능함을 보여준다. 그러나 절망이 아니라 은혜의 문을 여는 복음의 전제가 된다. 율법을 완전히 지키신 그리스도만이 우리의 의가 되신다.", "예화_적용": "병원에 가야 할 이유를 알려면 먼저 내가 아프다는 사실을 인정해야 한다. 율법은 영혼의 진단서이고, 복음은 처방전이다."},
    {"대지": "결론", "내용": "우리 모두는 율법 앞에 범죄자입니다. 그러나 그리스도께서 우리를 대신하여 율법의 요구를 완전히 충족하셨습니다. 이 은혜 안에서 우리는 정죄가 아니라 감사와 사랑으로 율법을 지키게 됩니다.", "예화_적용": "자유의 율법(2:12)은 정죄의 도구가 아니라 감사의 응답으로 살아가는 새로운 삶의 원리가 됩니다."}
  ],
