    {"구절": "딛 1:16", "연결점": "저희가 하나님을 시인하나 행위로는 부인하니 가증한 자요 복종치 아니하는 자요 모든 선한 일을 버리는 자니라", "구분": "신약"},
    {"구절": "요일 3:18", "연결점": "자녀들아 우리가 말과 혀로만 사랑하지 말고 오직 행함과 진실함으로 하자", "구분": "신약"}
