    {"구절": "요일 3:17", "연결점": "누가 이 세상 재물을 가지고 형제의 궁핍함을 보고도 도와줄 마음을 닫으면 하나님의 사랑이 어찌 그 속에 거할까 보냐", "구분": "신약"},
    {"구절": "갈 6:10", "연결점": "그러므로 우리는 기회 있는 대로 모든 이에게 착한 일을 하되 더욱 믿음의 가정들에게 할지니라", "구분": "신약"}
