    {"항목": "산불의 비유", "내용": "팔레스타인의 건조한 기후에서 산불은 매우 심각한 재해였다. 작은 불씨 하나가 온 산림을 태울 수 있었다. 야고보의 독자들은 이 비유를 생생하게 이해했을 것이다. 구약에서도 불은 혀의 파괴력을 묘사하는 데 자주 사용되었다(잠 16:27, 잠 26:20-21)", "목회적활용": "말 한 마디의 파괴력을 구체적으로 가르치라. 뒷담화, 비방, 거짓말 등이 공동체에 미치는 파괴적 영향을 인식시키라"},
    {"항목": "세 번째 비유의 절정", "내용": "재갈(3절)→키(4절)→불(5절)로 이어지는 비유가 절정에 달한다. 재갈과 키는 제어의 비유였지만, 불은 파괴의 비유로 전환된다. 혀가 제어되지 않을 때의 결과가 불처럼 파괴적임을 경고한다", "목회적활용": "말의 제어(3-4절)에서 실패할 때의 결과(5절 이하)를 대비시키며, 말의 절제의 긴급성을 강조하라"}
