    {"대지": "서론", "내용": "인간은 사자를 길들이고, 독수리를 훈련시키고, 돌고래와 소통합니다. 그런데 자기 혀 하나를 길들이지 못합니다. 이 역설이 야고보의 메시지입니다.", "예화_적용": "우주를 탐험하는 인류가 가정에서 한 마디 말다툼을 해결하지 못하는 아이러니."},
    {"대지": "1대지: 인간의 놀라운 능력 (만물 통치)", "내용": "하나님이 인간에게 주신 만물 통치의 능력은 놀랍다. 모든 종류의 동물을 길들인다.", "예화_적용": "서커스에서 호랑이가 재주를 부리고, 수족관에서 범고래가 훈련받는 것을 봅니다."},
    {"대지": "2대지: 인간의 근본적 한계 (혀의 불능)", "내용": "그러나 혀만은 길들이지 못한다(8절). 외부 세계는 정복하면서 내면 세계는 정복하지 못하는 비극.", "예화_적용": "가장 성공한 CEO도 화가 나면 말실수를 합니다. 지위와 능력이 혀를 보장하지 않습니다."},
    {"대지": "3대지: 성령의 은혜만이 (유일한 해결책)", "내용": "인간의 본성으로 불가능한 것을 성령의 능력으로 가능케 하신다. 혀의 문제는 자기 노력이 아니라 은혜의 영역이다.", "예화_적용": "자동차의 파워 스티어링처럼, 성령의 도움이 우리의 약한 의지를 보조합니다."},
    {"대지": "결론", "내용": "동물을 길들이는 능력보다 더 중요한 것은 혀를 길들이는 것입니다. 이것은 인간의 힘으로 불가능하지만 성령의 도움으로 가능합니다.", "예화_적용": "매일 '성령님, 오늘 제 혀를 다스려 주소서'라고 기도하십시오."}
